//! Round-trip T3 wire JSON through the generated Rust types.
//!
//! * `fixtures/samples/<Def>.json`: values generated by Effect's `Arbitrary` from T3's own
//!   schemas and encoded with T3's JSON codec (regen.sh --samples). Every one must
//!   deserialize and re-serialize to the same JSON (modulo `null` vs absent keys and
//!   integer-vs-float spelling).
//! * `fixtures/t3-tests/<Def>[.label].json`: values copied from T3's contract tests;
//!   regen.sh checks they still decode with T3's codec and writes T3's own re-encoding to
//!   `fixtures/t3-tests-canonical/`, which is the expected Rust output.

use std::{collections::BTreeMap, fs, path::Path};

use serde::{Serialize, de::DeserializeOwned};
use serde_json::Value;

mod dispatch {
    use super::rt;
    include!("../src/generated/dispatch.rs");
}

fn rt<T: DeserializeOwned + Serialize>(v: Value) -> Result<Value, String> {
    let t: T = serde_json::from_value(v).map_err(|e| e.to_string())?;
    serde_json::to_value(&t).map_err(|e| e.to_string())
}

/// Optional keys are emitted as `null` by Effect's JSON codec but skipped by serde;
/// numbers may come back as `1.0` for `1`. Normalize both away before comparing.
fn norm(v: &Value) -> Value {
    match v {
        Value::Object(m) => Value::Object(
            m.iter()
                .filter(|(_, v)| !v.is_null())
                .map(|(k, v)| (k.clone(), norm(v)))
                .collect(),
        ),
        Value::Array(a) => Value::Array(a.iter().map(norm).collect()),
        Value::Number(n) => serde_json::Number::from_f64(n.as_f64().unwrap())
            .map(Value::Number)
            .unwrap_or(Value::Null),
        _ => v.clone(),
    }
}

/// First differing JSON path, for readable failures.
fn diff(a: &Value, b: &Value, path: &str) -> Option<String> {
    match (a, b) {
        (Value::Object(x), Value::Object(y)) => {
            for k in x.keys().chain(y.keys()) {
                match (x.get(k), y.get(k)) {
                    (Some(p), Some(q)) => {
                        if let Some(d) = diff(p, q, &format!("{path}.{k}")) {
                            return Some(d);
                        }
                    }
                    (p, q) => return Some(format!("{path}.{k}: {p:?} vs {q:?}")),
                }
            }
            None
        }
        (Value::Array(x), Value::Array(y)) if x.len() == y.len() => x
            .iter()
            .zip(y)
            .enumerate()
            .find_map(|(i, (p, q))| diff(p, q, &format!("{path}[{i}]"))),
        _ if a == b => None,
        _ => Some(format!("{path}: {} vs {}", trunc(a), trunc(b))),
    }
}

fn trunc(v: &Value) -> String {
    let s = v.to_string();
    if s.len() > 120 {
        format!("{}…", &s[..120])
    } else {
        s
    }
}

fn check(def: &str, v: Value) -> Result<(), String> {
    let out =
        dispatch::roundtrip(def, v.clone()).ok_or_else(|| format!("no Rust type for {def}"))??;
    match diff(&norm(&v), &norm(&out), "$") {
        None => Ok(()),
        Some(d) => Err(format!("lossy round-trip: {d}")),
    }
}

#[test]
fn samples_roundtrip() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/samples");
    let mut files: Vec<_> = fs::read_dir(&dir)
        .expect("samples dir")
        .map(|e| e.unwrap().path())
        .collect();
    files.sort();
    let (mut types, mut values) = (0, 0);
    let mut failures: BTreeMap<String, String> = BTreeMap::new();
    for path in files {
        let def = path.file_stem().unwrap().to_str().unwrap().to_string();
        let samples: Vec<Value> =
            serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        types += 1;
        for (i, v) in samples.into_iter().enumerate() {
            values += 1;
            if let Err(e) = check(&def, v) {
                failures
                    .entry(def.clone())
                    .or_insert(format!("sample {i}: {e}"));
            }
        }
    }
    eprintln!(
        "samples: {types} types, {values} values, {} types with failures",
        failures.len()
    );
    for (def, e) in &failures {
        eprintln!("  FAIL {def}: {e}");
    }
    assert!(
        failures.is_empty(),
        "{} of {types} sampled types failed to round-trip",
        failures.len()
    );
}

#[test]
fn t3_test_fixtures() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/t3-tests");
    let mut files: Vec<_> = fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    files.sort();
    let mut results = BTreeMap::new();
    for path in files {
        let name = path.file_name().unwrap().to_str().unwrap().to_string();
        let def = name.split('.').next().unwrap().to_string();
        let v: Value = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        // Oracle: T3's own decode->encode of the fixture (written by regen.sh), so keys the
        // schema doesn't declare (and that T3 drops too) don't count as losses.
        let canonical = dir.join("../t3-tests-canonical").join(&name);
        let expected = fs::read_to_string(&canonical)
            .ok()
            .map(|s| serde_json::from_str::<Value>(&s).unwrap());
        let r = match expected {
            None => check(&def, v),
            Some(exp) => dispatch::roundtrip(&def, v).unwrap().and_then(|out| {
                match diff(&norm(&exp), &norm(&out), "$") {
                    None => Ok(()),
                    Some(d) => Err(format!("differs from T3's re-encoding: {d}")),
                }
            }),
        };
        results.insert(name, r);
    }
    for (name, r) in &results {
        eprintln!(
            "  {name}: {}",
            match r {
                Ok(()) => "ok".to_string(),
                Err(e) => e.clone(),
            }
        );
    }
    // Forward-compat fixtures (values a *newer* server may send) are reported, not asserted:
    // T3 decodes them leniently via catchDecoding, which JSON Schema cannot express.
    let hard: Vec<_> = results
        .iter()
        .filter(|(n, r)| r.is_err() && !n.contains("newer-server") && !n.contains("future-"))
        .collect();
    assert!(hard.is_empty(), "current-shape fixtures failed: {hard:?}");
}

#[test]
fn envelope_and_method_table() {
    use t3_api::{RpcMethod, envelope, rpc, types};
    assert_eq!(rpc::PullRequestsDetail::TAG, "pullRequests.detail");
    assert!(rpc::OrchestrationSubscribeThread::STREAM);
    assert!(rpc::ALL_TAGS.contains(&"pullRequests.diffFileContents"));

    let payload: types::PullRequestRef = serde_json::from_value(serde_json::json!({
        "projectId": "project-1", "repository": "pingdotgg/t3code", "number": 1
    }))
    .unwrap();
    let frame = envelope::request::<rpc::PullRequestsDetail>(
        envelope::RequestId::String("1".into()),
        &payload,
    )
    .unwrap();
    let wire = serde_json::to_value(&frame).unwrap();
    assert_eq!(wire["_tag"], "Request");
    assert_eq!(wire["tag"], "pullRequests.detail");
    assert_eq!(wire["payload"]["number"], 1);

    // A failure Exit carrying a typed T3 error plus an error tag this build doesn't know.
    let exit: envelope::FromServer = serde_json::from_value(serde_json::json!({
        "_tag": "Exit", "requestId": "1",
        "exit": { "_tag": "Failure", "cause": [
            { "_tag": "Fail", "error": { "_tag": "PullRequestOperationError", "operation": "detail", "detail": "boom" } },
            { "_tag": "Fail", "error": { "_tag": "SomeFutureError", "x": 1 } }
        ]}
    }))
    .unwrap();
    let envelope::FromServer::Exit { exit, .. } = exit else {
        panic!()
    };
    let envelope::Exit::Failure { cause } =
        envelope::decode_exit::<rpc::PullRequestsDetail>(exit).unwrap()
    else {
        panic!()
    };
    let envelope::CauseReason::Fail { error } = &cause[0] else {
        panic!()
    };
    assert_eq!(error.tag(), Some("PullRequestOperationError"));
    assert!(matches!(
        error,
        t3_api::tagged::PullRequestsDetailRpcError::PullRequestOperationError(_)
    ));
    let envelope::CauseReason::Fail { error } = &cause[1] else {
        panic!()
    };
    assert!(matches!(
        error,
        t3_api::tagged::PullRequestsDetailRpcError::Unrecognized(_)
    ));

    // JsNumber accepts Effect's non-finite spellings.
    let n: t3_api::JsNumber = serde_json::from_value(serde_json::json!("Infinity")).unwrap();
    assert!(n.0.is_infinite());
}
